import { generateSW } from "workbox-build";
import type { Plugin } from "vite";

/**
 * The service worker, generated by hand because the plugin will not.
 *
 * `vite-plugin-pwa` writes the manifest and copies the icons under Start, and
 * then never writes a worker: its `closeBundle` fires, but Start builds two
 * environments and the plugin keeps the last resolved config it saw — the SSR
 * one — so by the time it runs it believes it is in a server build and returns
 * early. Nothing in its options reaches that decision.
 *
 * So the manifest stays with the plugin, which does that part correctly, and
 * the worker is generated here from the finished client build. It is forty
 * lines, it runs at a moment we choose, and the caching rules below are ones
 * this app actually needs rather than the defaults.
 */
export function serviceWorker(): Plugin {
  return {
    name: "whistleday:service-worker",
    apply: "build",

    // Both environments fire this hook; only the client one has anything to
    // cache. `dist/server` is a Node bundle nobody fetches.
    closeBundle: {
      sequential: true,
      order: "post",
      async handler() {
        const environment = (this as { environment?: { name?: string } }).environment;
        if (environment?.name !== "client") return;

        const { count, size, warnings } = await generateSW({
          globDirectory: "dist/client",

          /**
           * No HTML. The glob would otherwise match 135 prerendered marketing
           * pages, and an organiser opening the wizard would download every
           * "12 team round robin" page ever written onto their phone before
           * their tournament started. What the app needs to start from the
           * device is its code, not its content marketing.
           */
          globPatterns: ["**/*.{js,css,svg,png,woff2}", "manifest.webmanifest"],
          swDest: "dist/client/sw.js",

          /**
           * There is no app shell to fall back to, and that is a consequence
           * of prerendering rather than an oversight.
           *
           * The old SPA build had one `index.html` that booted any route, so a
           * navigation offline could be answered with it. Under Start every
           * prerendered page is its own document and the app screens are
           * rendered per request, so there is no single file that means "the
           * app". Serving one route's HTML for another's URL would hydrate a
           * router into markup for a page it is not on.
           *
           * NetworkFirst is the honest answer instead: the screen somebody was
           * on is the screen they get back. An organiser has had `/t/{id}` open
           * since nine o'clock, so it is in the cache by the time the hall's
           * wifi gives out, and a reload returns it. A URL nobody has visited
           * cannot be served offline, which is true of any design that is not
           * lying about what it has.
           *
           * Four seconds because a hall's wifi fails by hanging rather than by
           * refusing — waiting out a dead socket is the thing this is for.
           */
          runtimeCaching: [
            {
              urlPattern: ({ request, url }: { request: Request; url: URL }) =>
                request.mode === "navigate" &&
                /^\/(t|display|m|join|account|new)(\/|$)/.test(url.pathname),
              handler: "NetworkFirst",
              options: {
                cacheName: "screens",
                networkTimeoutSeconds: 4,
                expiration: { maxEntries: 32, maxAgeSeconds: 60 * 60 * 24 * 7 },
              },
            },
          ],

          /**
           * `/api` is deliberately absent, and stays absent.
           *
           * Writes must never be intercepted: a queued result a worker
           * answered from a cache would look sent and never arrive. And
           * `/api/display/{token}` is read with `If-None-Match` and answers
           * 304 — a cache in the middle of a conditional request is a good way
           * to pin a wall to a payload from an hour ago. Workbox only handles
           * what it has a route for, so everything else reaches the network
           * exactly as it did before.
           */
          navigationPreload: false,

          // The projector can be open for eight hours across a deploy.
          // Claiming the page mid-tournament would reload the wall; this takes
          // over on the next load, which is after the day has finished.
          skipWaiting: false,
          clientsClaim: false,
          cleanupOutdatedCaches: true,
        });

        for (const warning of warnings) this.warn(warning);
        this.info(
          `service worker: ${count} files precached, ${(size / 1024).toFixed(0)} kB`,
        );
      },
    },
  };
}
